import json

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find background (most common value)
    count = {}
    for row in grid:
        for val in row:
            count[val] = count.get(val, 0) + 1
    bg = max(count, key=count.get)

    # Create result as copy of input
    result = [row[:] for row in grid]

    # Find all pairs of diagonally connected same-value cells
    # Then extend the line from the second cell through background cells
    for r1 in range(h):
        for c1 in range(w):
            if grid[r1][c1] == bg:
                continue
            val = grid[r1][c1]

            for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                r2, c2 = r1 + dr, c1 + dc

                # Check if there's a same-value cell diagonally adjacent
                if 0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == val:
                    # Extend from (r2,c2) in direction (dr, dc)
                    nr, nc = r2, c2
                    nr += dr
                    nc += dc
                    while 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg:
                        result[nr][nc] = val
                        nr += dr
                        nc += dc

    return result

